    { term: "Sovereignty", def: "The power of a state to rule itself within its area without external control." },
    { term: "Recognition", def: "Acceptance of the existence of a state; one of the features a state must have." },
    { term: "Theocratic state", def: "An early state ruled by priests, which arose as religion developed and priests took central roles in administration." },
    { term: "Elite", def: "A rich person who attained higher status in society because of wealth, often those who produced surplus in early society." }
